'use strict';
const fs=require('fs'),path=require('path'),assert=require('assert'),crypto=require('crypto'),E=require('./features');
const root=path.resolve(__dirname,'..'),out=process.env.NARUTO_EDITOR_TEST_OUT||path.join(root,'evidence/editor_v020'),baseline=fs.readFileSync(path.join(root,'build/naruto_fog_harbor_sample_v0.1.0.gba'));
fs.mkdirSync(out,{recursive:true});const hash=b=>crypto.createHash('sha256').update(b).digest('hex'),checks=[];
function test(label,fn){fn();checks.push(label);console.log('PASS',label);}
const fresh=()=>new E.Editor(baseline),provider=()=>Uint8Array.from(Array(32).fill(255));
test('no-edit exact byte identity with extension loaded',()=>assert.deepEqual(fresh().build(provider),new Uint8Array(baseline)));
test('all 46 native maps decode and render within dimensions',()=>{const m=fresh();for(let s=1;s<=46;s++){const d=m.mapData(s),r=m.renderMap(s);assert.equal(r.width,d.width*32);assert.equal(r.height,d.height*16);assert.equal(r.pixels.length,r.width*r.height*4);assert(new Set(r.pixels).size>10);}});
test('LZ literal encoder matches native resource decoder',()=>{const m=fresh();for(let s=1;s<=46;s++){const terrain=m.mapData(s).terrain;assert.deepEqual(E.decompress(Uint8Array.from(E.compressLiteral(terrain)),0),terrain);}});
test('map stamping and terrain append without changing shared source blocks',()=>{const m=fresh(),source=m.mapData(1),p=source.descriptor,old=E.u32(m.rom,p+12)-E.BASE;m.stampCell(1,9,8,6,9);m.setTerrain(1,9,8,7);const result=m.build(provider),reopen=new E.Editor(result),d=reopen.mapData(1);assert.equal(d.terrain[(8*15+9)*2],7);for(let j=0;j<2;j++)assert.equal(d.layers[0][(8*30+18+j)*2],source.layers[0][(9*30+12+j)*2]);assert.deepEqual(result.slice(old,old+16),m.rom.slice(old,old+16));assert(E.u32(result,p+12)-E.BASE>=baseline.length);assert.deepEqual(reopen.mapData(2).terrain,source.stage===2?source.terrain:m.mapData(2).terrain);});
test('map edits undo and invalid coordinates roll back',()=>{const m=fresh();m.transaction('map',()=>m.setTerrain(1,8,5,0));assert(m.hasExtraChanges());m.undo();assert(!m.hasExtraChanges());assert.throws(()=>m.transaction('bad map',()=>m.setTerrain(1,99,1,0)));assert(!m.hasExtraChanges());});
const event=(type='turn',repeat='once')=>({label:'Example',type,repeat,phase:0,sub:3,turn:2,side:1,character:17,pages:[{speaker:7,text:'First page.【分页】Second page.'},{speaker:12,text:'Understood.'}]});
test('new events compile to native scripts with valid branches and pages',()=>{const m=fresh();m.setEvents(1,[event(),event('turn','phase'),event('absent')]);const result=m.build(provider),reopen=new E.Editor(result),g=reopen.scripts(1);assert.deepEqual(g.issues,[]);assert.equal(reopen.events(1).length,3);assert.equal(reopen.dialogues(1).length,m.dialogues(1).length+9);assert(g.nodes.some(n=>n.op===55&&result[n.offset+1]===0));});
test('reopened event ROM unchanged project keeps exact bytes',()=>{const m=fresh();m.setEvents(1,[event()]);const bytes=m.build(provider),a=new E.Editor(bytes),project=a.project(hash(bytes)),b=new E.Editor(bytes);b.importProject(project,hash(bytes));assert.deepEqual(b.build(provider),bytes);});
test('event definitions survive ROM reopen and support removal',()=>{const m=fresh();m.setEvents(1,[event()]);const a=m.build(provider),reopen=new E.Editor(a);assert.deepEqual(reopen.build(provider),a);reopen.setEvents(1,[]);const b=reopen.build(provider);assert.equal(E.u32(b,0x60e38),E.u32(baseline,0x60e38));assert.equal(E.u32(b,0x60ef4),E.u32(baseline,0x60ef4));});
test('project roundtrip preserves maps, events, output and original base pointers',()=>{const m=fresh();m.stampCell(1,2,4,6,8);m.setTerrain(1,4,8,7);m.setEvents(1,[event()]);const project=m.project(hash(baseline)),other=fresh();other.importProject(JSON.parse(JSON.stringify(project)),hash(baseline));assert.deepEqual(other.build(provider),m.build(provider));const bad=JSON.parse(JSON.stringify(project));bad.features.bases[1].logic=0;const safe=fresh();safe.importProject(bad,hash(baseline));assert.deepEqual(safe.build(provider),m.build(provider));});
test('native event slots stay intact when new events are added',()=>{const source=fs.readFileSync(path.join(root,'originals/naruto_konoha_bearteam_simp.gba')),m=new E.Editor(source);m.setEvents(1,[event()]);const result=m.build(provider),before=E.u32(source,0x60ef4)-E.BASE,after=E.u32(result,0x60ef4)-E.BASE;assert.deepEqual(result.slice(after,after+16*5),new Uint8Array(source.slice(before,before+16*5)));});
test('scene backgrounds and standalone story scenes remain readable',()=>{const m=fresh();for(const id of m.backgrounds()){const r=m.renderBackground(1,id);assert.equal(r.width,240);assert.equal(r.height,80);}assert.equal(m.renderBackground(50).id,9);assert.equal(m.renderBackground(54).id,13);for(let s=47;s<=55;s++)assert.deepEqual(m.scripts(s).issues,[]);});
test('reject excessive events, unsupported conditions and empty dialogue',()=>{const m=fresh();assert.throws(()=>m.setEvents(1,Array.from({length:9},()=>event())));assert.throws(()=>m.setEvents(1,[{...event(),type:'unknown'}]));assert.throws(()=>m.setEvents(1,[{...event(),pages:[]} ]));});
test('large appended dialogue metadata reopens without truncation',()=>{const m=fresh(),e=event();e.pages=Array.from({length:50},()=>({speaker:7,text:Array(40).fill('A'.repeat(48)).join('【分页】')}));m.setEvents(1,[e]);const b=m.build(provider),r=new E.Editor(b);assert.equal(r.events(1)[0].pages[49].text,e.pages[49].text);assert.deepEqual(r.scripts(1).issues,[]);});
fs.writeFileSync(path.join(out,'feature_core_tests.json'),JSON.stringify({result:'pass',baseline_sha256:hash(baseline),checks},null,2));console.log(checks.length,'feature checks passed');
